"""Build the reviewed bilingual catalog from saved manufacturer observations.
Usage: python curate.py /path/to/gear-sources /path/to/equipment-catalog.json
Facts belong to the named variant; missing facts remain absent. No prices or stock.
"""
import json, pathlib, sys
from urllib.parse import urljoin

root=pathlib.Path(__file__).parent
observations=json.load(open(pathlib.Path(sys.argv[1])/'observations.json'))
previous=json.load(open(sys.argv[2]))
sources={r['name']:r for r in observations}
old={r['name']:r for r in previous}
items=[]
def add(name,ar,category,description_ar,description_en,facts,methods=None,**extra):
    s=sources[name]
    if s.get('status')!=200: raise ValueError('Unverified source: '+name)
    items.append(dict(name=name,id=old.get(name,{}).get('id'),name_ar=ar,category=category,
      description_ar=description_ar,description_en=description_en,facts={k:list(v) for k,v in facts.items()},
      methods=methods if methods is not None else old.get(name,{}).get('suitable_brew_methods',[]),
      source={k:s.get(k) for k in ['url','final_url','title','checked_at','sha256','image_url']},**extra))
