for item in items:
    # No generic logo, homepage banner or wrong-generation product photo.
    if not item.pop('image_verified'): item['source']['image_url']=None
    if item['source']['image_url'] and item['source']['image_url'].startswith('http://'):item['source']['image_url']='https://'+item['source']['image_url'][7:]
    if item['source']['image_url'] and item['source']['image_url'].startswith('//'):item['source']['image_url']='https:'+item['source']['image_url']
    if item['source']['image_url']:item['source']['image_url']=urljoin(item['source']['final_url'] or item['source']['url'],item['source']['image_url'])
json.dump({'schema_version':1,'items':items},open(root/'catalog.json','w'),ensure_ascii=False,indent=2)
json.dump(previous,open(root/'before.json','w'),ensure_ascii=False,indent=2)
print(json.dumps({'models':len(items),'existing':sum(bool(i['id']) for i in items),'new':sum(not i['id'] for i in items),'facts':sum(len(i['facts']) for i in items)}))
